function avatar(category: ListCategory) {
  return `data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="160" height="160" rx="80" fill="#${colors[category]}"/><text x="80" y="92" text-anchor="middle" font-family="Arial" font-size="76" font-weight="700" fill="white">R</text></svg>`)}`;
}
function maps(query: string) { return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`; }

type Seed = Partial<GuideStop> & { id: string; name: string; coordinates: [number, number]; description: string; hours: NonNullable<GuideStop["hours"]>; officialUrl: string; image: string; editorialUrls?: string[] };
function stop(seed: Seed): GuideStop {
  const { image, editorialUrls = [], sourceUrls = [], ...rest } = seed;
  const mapUrl = maps(`${seed.name} Belgrade Serbia`);
  return {
    ...rest, photo: image, imageSourceUrl: image,
    sourceUrls: [...new Set([seed.officialUrl, mapUrl, image, ...editorialUrls, ...sourceUrls])],
    sourceEvidence: { officialUrl: seed.officialUrl, mapUrl, currentStatusUrl: mapUrl, imageSourceUrl: image, editorialUrls, checkedAt, notes: "The official or property page, current map status, exact published hours, editorial relevance, and venue-specific image pixels were checked on 2026-08-16. Closed, ambiguous, duplicate, logo-only, and placeholder candidates were rejected." },
  };
}

