function sourcesFor(stops: GuideStop[], categoryUrl: string, categoryName: string): ListSource[] {
  return [{ name: categoryName, url: categoryUrl }, { name: "Belgrade official tourism", url: tourism }, ...stops.map((item) => ({ name: `${item.name} official/property source`, url: item.officialUrl! }))];
}
function guide(category: ListCategory, id: string, slug: string, seoSlug: string, title: string, description: string, stops: GuideStop[], categorySource: string, seoTitle: string, seoDescription: string): MapList {
  return { id, slug, seoSlug, seoTitle, seoDescription, title, description, url: maps(`${title} Belgrade Serbia`), category, location, creator: { id: `user-rguide-${category.toLowerCase()}`, name: `R ${category}`, avatar: avatar(category) }, upvotes: 0, createdAt, stops, sources: sourcesFor(stops, categorySource, `${title} research index`) };
}

